console.log('PASS: '+paths.size+' GitHub images, 16 restricted Drive references, 10 curated cast portraits and one Ankita scene reference, unique character IDs.');


const universalJan=JSON.parse(readFileSync(resolve(ui,'src/data/sw-timeline-jan01.json'),'utf8'));
const universalFuture=JSON.parse(readFileSync(resolve(ui,'src/data/sw-timeline-future.json'),'utf8'));
const universalDhika=JSON.parse(readFileSync(resolve(ui,'src/data/dhika-universal-timeline.json'),'utf8'));
assert.equal(universalJan.anchorDate,'2026-01-01','Society Wives story anchor must be Jan 1 2026');
assert.equal(universalDhika.anchorDate,'2026-01-01','Dhika Day 1 must align to Society Wives Jan 1 2026');
assert.equal(universalJan.events.length,87,'Original January1 events retained plus four retimed Shreya EP03 working scenes');
assert.equal(universalJan.events.filter(e=>e.kind==='source-scene'&&e.episode==='02').length,67,'EP02 shared Taniya/Soniya source scenes must only appear once');
assert.equal(universalJan.events.filter(e=>e.kind==='source-scene'&&e.episode==='03').length,9,'Nine Episode03 source events including Ankita Scene05 car ride in reader');
assert.ok(!universalJan.events.some(e=>e.date!=='2026-01-01'),'Jan 1 clock contains an event from another date');
assert.deepEqual(universalJan.events.slice(0,2).map(e=>e.start),['06:20','06:29'],'January 1 event clock not sorted');
assert.equal(new Set(universalJan.events.map(e=>e.id)).size,87,'January 1 event IDs must all be unique');
const shifted=universalFuture.events.filter(e=>e.state==='rescheduled');
assert.equal(shifted.length,1,'Only Jan2 M08 remains in future; Shreya EP03 SR10–SR13 are now Jan1');
assert.equal(shifted.find(e=>e.scene==='M08')?.date,'2026-01-02');
assert.equal(universalFuture.events.filter(e=>e.lead==='Shreya'&&/^SR1[0-3]$/.test(e.scene||'')).length,0,'No obsolete Shreya Jan3 events in future timeline');
assert.deepEqual(universalJan.events.filter(e=>e.id.startsWith('e03-shreya-SR')).map(e=>e.scene).sort(),['SR10','SR11','SR12','SR13']);
assert.ok(universalJan.events.filter(e=>e.lead==='Shreya'&&e.kind==='source-scene'&&e.episode==='02').every(e=>e.state==='approved-prose'),'All Shreya source scenes must have approved badges');
assert.equal(universalJan.events.find(e=>e.scene==='SR03'&&e.lead==='Shreya')?.status,'Author-approved plot · full prose not published');
assert.ok(sourcePlanning.includes('Two distinct helpers'),'Shreya Planning must distinguish society Chintu and station chai wala');
assert.ok(sourcePlanning.includes('shreyaEpisode03Proposal.timeline.map'),'Shreya proposed Jan1 timeline must render in UI');
assert.ok(!sourcePlanning.includes('<strong>Date:</strong> 3 January 2026'),'UI must not show superseded active date');
assert.ok(universalFuture.events.filter(e=>e.episode==='01').every(e=>e.date===null),'Undated prologue must not be silently placed on Jan 1');
assert.equal(universalDhika.episodesIndexed,41,'All Dhika episodes must be indexed');
assert.equal(new Set(universalDhika.events.map(e=>e.episode)).size,41,'Dhika episode index incomplete');
for(let day=1;day<=11;day++)assert.ok(universalDhika.events.some(e=>e.storyDay===day&&e.date===new Date(Date.UTC(2026,0,day)).toISOString().slice(0,10)),'Dhika story Day '+day+' misaligned');
const earlyDhika=universalDhika.events.filter(e=>e.episode==='EP04');
assert.ok(earlyDhika.some(e=>e.date==='2026-01-01')&&earlyDhika.some(e=>e.date==='2026-01-02'),'Dhika EP04 must straddle Day 1/Day 2');
const rootCorpus=JSON.parse(readFileSync(resolve(root,'../data/corpus.json'),'utf8'));
assert.ok(universalJan.events.some(e=>e.id==='ep03-ankita-scene04'&&e.date==='2026-01-01'),'Rohit intro must be Jan 1, before any first look');
assert.equal(universalJan.events.filter(e=>e.id.startsWith('ep03-ankita-scene')).length,8,'Ankita eight EP03 scenes indexed in Jan1 timeline');
assert.ok(universalJan.events.some(e=>e.id==='ep03-ankita-scene08'&&e.start==='18:10'&&e.end==='18:25'&&e.source==='episode-03-ankita-scene-08-rinku-setup.json'),'Rinku setup missing from Jan1 18:10–18:25');
assert.equal(universalFuture.events.filter(e=>e.id.startsWith('date-pending-ankita-')).length,0,'Discarded old home followups must not appear as active timeline events');
assert.deepEqual(universalFuture.events.filter(e=>e.id.startsWith('future-ankita-rohit-')).map(e=>e.date),['2026-01-02','2026-01-02'],'Rohit accident and first show must both be Jan 2');
for(const event of universalDhika.events){
 const ep=rootCorpus.episodes.find(x=>x.id===event.episode);
 assert.ok(ep&&ep.lines[event.firstLineIndex],'Invalid Dhika paragraph pointer '+event.id);
 assert.ok(event.lastLineIndex<ep.lines.length,'Dhika range extends beyond original source '+event.id);
 if(event.arcRelativeDay)assert.equal(event.date,null,'Arc-relative Day 1 must never reset to Jan 1');
}
console.log('PASS: 83 cross-lead Jan1 events, including silent Gopal Scene07 and Rinku doorbell Scene08; superseded followups removed.');
